{
  "name": "ATON TECH Solutions",
  "description": "A premium, modern corporate website for ATON TECH Solutions Private Limited, a cutting-edge software development company specializing in e-commerce, enterprise applications, and AI-driven systems.",
  "requestFramePermissions": []
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

import React, { useState, useEffect } from 'react';
import Navbar from './components/Navbar';
import Hero from './components/Hero';
import About from './components/About';
import Services from './components/Services';
import Process from './components/Process';
import TechStack from './components/TechStack';
import Clients from './components/Clients';
import WhyChooseUs from './components/WhyChooseUs';
import Testimonials from './components/Testimonials';
import Contact from './components/Contact';
import Footer from './components/Footer';
import FloatingWhatsApp from './components/FloatingWhatsApp';
import { Toaster } from 'react-hot-toast';

const App: React.FC = () => {
  const [isScrolled, setIsScrolled] = useState(false);

  useEffect(() => {
    const handleScroll = () => {
      setIsScrolled(window.scrollY > 50);
    };
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  return (
    <div className="relative min-h-screen bg-white overflow-x-hidden">
      <Toaster position="top-right" />
      <Navbar isScrolled={isScrolled} />

      <main>
        <section id="home">
          <Hero />
        </section>

        <section id="about" className="py-20">
          <About />
        </section>

        <section id="services" className="py-20 bg-gray-50">
          <Services />
        </section>

        <section id="process" className="py-20">
          <Process />
        </section>

        <section id="technology-stack" className="py-20 bg-gray-50">
          <TechStack />
        </section>

        <section id="our-clients" className="py-20">
          <Clients />
        </section>

        <section id="why-choose-us" className="py-20 bg-gray-900 text-white">
          <WhyChooseUs />
        </section>

        <section id="testimonials" className="py-20 bg-gray-50">
          <Testimonials />
        </section>

        <section id="contact-us" className="py-20">
          <Contact />
        </section>

        {/* Call to Action Section before Footer */}
        <section className="py-16 bg-blue-gradient text-white text-center">
          <div className="max-w-4xl mx-auto px-4">
            <h2 className="text-3xl md:text-4xl font-bold mb-6 font-display">Ready to Build Your Digital Future?</h2>
            <p className="text-lg opacity-90 mb-8">Let's discuss how we can transform your business with our expertise.</p>
            <a 
              href="#contact-us"
              className="inline-block px-10 py-4 rounded-full bg-orange-gradient text-white font-bold text-lg hover:shadow-xl hover:scale-105 transition-all"
            >
              Get Free Consultation
            </a>
          </div>
        </section>
      </main>

      <Footer />
      <FloatingWhatsApp />
    </div>
  );
};

export default App;

export interface ServiceCardProps {
