import React, { useState } from 'react';
import { Menu, X } from 'lucide-react';

interface NavbarProps {
  isScrolled: boolean;
}

const Navbar: React.FC<NavbarProps> = ({ isScrolled }) => {
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);

  const navLinks = [
    { name: 'Home', href: '#home' },
    { name: 'About', href: '#about' },
    { name: 'Services', href: '#services' },
    { name: 'Process', href: '#process' },
    { name: 'Tech Stack', href: '#technology-stack' },
    { name: 'Clients', href: '#our-clients' },
    { name: 'Why Choose Us', href: '#why-choose-us' },
    { name: 'Contact', href: '#contact-us' },
  ];

  return (
    <nav className={`fixed top-0 left-0 right-0 z-50 transition-all duration-300 ${isScrolled ? 'bg-white shadow-md py-3' : 'bg-transparent py-5'}`}>
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex justify-between items-center">
          <div className="flex items-center space-x-2">
            {/* Logo placeholder */}
            <div className="w-10 h-10 bg-blue-gradient rounded-lg flex items-center justify-center text-white font-bold text-xl shadow-lg">A</div>
            <div className={`font-display font-bold text-xl tracking-tight ${isScrolled ? 'text-deepBlue' : 'text-white'}`}>
              ATON <span className="text-vibrantOrange">TECH</span>
            </div>
          </div>

          <div className="hidden lg:flex items-center space-x-8">
            {navLinks.map((link) => (
              <a 
                key={link.name} 
                href={link.href} 
                className={`font-medium transition-colors hover:text-vibrantOrange ${isScrolled ? 'text-gray-700' : 'text-white'}`}
              >
                {link.name}
              </a>
            ))}
            <a 
              href="#contact-us"
              className="bg-orange-gradient text-white px-6 py-2.5 rounded-full font-bold shadow-lg hover:shadow-xl hover:scale-105 transition-all"
            >
              Get Free Consultation
            </a>
          </div>

          <div className="lg:hidden flex items-center">
            <button 
              onClick={() => setMobileMenuOpen(!mobileMenuOpen)}
              className={`${isScrolled ? 'text-deepBlue' : 'text-white'}`}
            >
              {mobileMenuOpen ? <X size={28} /> : <Menu size={28} />}
            </button>
          </div>
        </div>
      </div>

      {/* Mobile Menu */}
      <div className={`lg:hidden transition-all duration-300 overflow-hidden ${mobileMenuOpen ? 'max-h-screen bg-white opacity-100 py-6 border-b' : 'max-h-0 opacity-0'}`}>
        <div className="px-4 space-y-4">
          {navLinks.map((link) => (
            <a 
              key={link.name} 
              href={link.href} 
              onClick={() => setMobileMenuOpen(false)}
              className="block text-gray-800 font-medium text-lg hover:text-vibrantOrange"
            >
              {link.name}
            </a>
          ))}
          <a 
            href="#contact-us"
            onClick={() => setMobileMenuOpen(false)}
            className="block text-center bg-orange-gradient text-white py-3 rounded-lg font-bold"
          >
            Get Free Consultation
          </a>
        </div>
      </div>
    </nav>
  );
};

export default Navbar;

