import React, { useState } from 'react';
import { Send, Phone, Mail, MapPin } from 'lucide-react';
import { submitContactForm } from '../services/supabase';
import toast from 'react-hot-toast';

const Contact: React.FC = () => {
  const [formData, setFormData] = useState({
    fullName: '',
    email: '',
    phone: '',
    companyName: '',
    message: ''
  });
  const [isSubmitting, setIsSubmitting] = useState(false);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
    setFormData(prev => ({ ...prev, [e.target.name]: e.target.value }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmitting(true);

    try {
      const success = await submitContactForm(formData);
      if (success) {
        toast.success("Message sent successfully! We'll get back to you soon.");
        setFormData({ fullName: '', email: '', phone: '', companyName: '', message: '' });
      } else {
        toast.error("Failed to send message. Please try again.");
      }
    } catch (error) {
      toast.error("Something went wrong. Please check your connection.");
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
      <div className="grid lg:grid-cols-2 gap-16">
        <div className="space-y-12">
          <div className="space-y-6">
            <h2 className="text-4xl font-display font-bold text-deepBlue">Let's Connect</h2>
            <p className="text-gray-600 text-lg">
              Have a groundbreaking idea? Let's discuss how our technical expertise can turn it into reality.
            </p>
          </div>

          <div className="space-y-8">
            <div className="flex items-center space-x-6">
              <div className="w-14 h-14 rounded-full bg-blue-50 text-royalBlue flex items-center justify-center flex-shrink-0 shadow-sm">
                <Mail size={24} />
              </div>
              <div>
                <p className="text-gray-500 font-medium">Email Us</p>
                <a href="mailto:atontechsolutions@gmail.com" className="text-xl font-bold text-deepBlue hover:text-royalBlue transition-colors">
                  atontechsolutions@gmail.com
                </a>
              </div>
            </div>

            <div className="flex items-center space-x-6">
              <div className="w-14 h-14 rounded-full bg-orange-50 text-vibrantOrange flex items-center justify-center flex-shrink-0 shadow-sm">
                <Phone size={24} />
              </div>
              <div>
                <p className="text-gray-500 font-medium">Call Us</p>
                <p className="text-xl font-bold text-deepBlue">+91 XXXXXXXXXX</p>
              </div>
            </div>

            <div className="flex items-center space-x-6">
              <div className="w-14 h-14 rounded-full bg-gray-50 text-gray-600 flex items-center justify-center flex-shrink-0 shadow-sm">
                <MapPin size={24} />
              </div>
              <div>
                <p className="text-gray-500 font-medium">Our Presence</p>
                <p className="text-xl font-bold text-deepBlue">Available Globally</p>
              </div>
            </div>
          </div>
        </div>

        <div className="bg-white p-8 md:p-12 rounded-3xl shadow-2xl border border-gray-100">
          <form onSubmit={handleSubmit} className="space-y-6">
            <div className="grid md:grid-cols-2 gap-6">
              <div className="space-y-2">
                <label className="text-sm font-bold text-gray-700">Full Name</label>
                <input 
                  type="text" required name="fullName" value={formData.fullName} onChange={handleChange}
                  className="w-full px-5 py-3 rounded-xl bg-gray-50 border border-gray-200 focus:border-royalBlue focus:ring-2 focus:ring-royalBlue/20 outline-none transition-all"
                  placeholder="John Doe"
                />
              </div>
              <div className="space-y-2">
                <label className="text-sm font-bold text-gray-700">Email Address</label>
                <input 
                  type="email" required name="email" value={formData.email} onChange={handleChange}
                  className="w-full px-5 py-3 rounded-xl bg-gray-50 border border-gray-200 focus:border-royalBlue focus:ring-2 focus:ring-royalBlue/20 outline-none transition-all"
                  placeholder="john@example.com"
                />
              </div>
            </div>

            <div className="grid md:grid-cols-2 gap-6">
              <div className="space-y-2">
                <label className="text-sm font-bold text-gray-700">Phone Number</label>
                <input 
                  type="tel" required name="phone" value={formData.phone} onChange={handleChange}
                  className="w-full px-5 py-3 rounded-xl bg-gray-50 border border-gray-200 focus:border-royalBlue focus:ring-2 focus:ring-royalBlue/20 outline-none transition-all"
                  placeholder="+91..."
                />
              </div>
              <div className="space-y-2">
                <label className="text-sm font-bold text-gray-700">Company Name</label>
                <input 
                  type="text" name="companyName" value={formData.companyName} onChange={handleChange}
