/**
 * Dynamically loads the SmtpJS script if it hasn't been loaded yet.
 * This is a robust way to ensure third-party dependencies are available.
 */
const loadSmtpScript = (): Promise<void> => {
  return new Promise((resolve, reject) => {
    if ((window as any).Email) {
      resolve();
      return;
    }

    const script = document.createElement('script');
    script.src = "https://smtpjs.com/v3/smtp.js";
    script.async = true;
    script.onload = () => {
      if ((window as any).Email) {
        resolve();
      } else {
        reject(new Error("SmtpJS loaded but Email object not found."));
      }
    };
    script.onerror = () => reject(new Error("Failed to load SmtpJS script from CDN."));
    document.head.appendChild(script);
  });
};

/**
 * Helper to wait for the external SmtpJS script to be ready on the window object.
 * First tries to load the script dynamically, then polls as a fallback.
 */
const waitForEmailObject = async (maxRetries = 25, interval = 200): Promise<any> => {
  try {
    // Attempt dynamic load first
    await loadSmtpScript();

    // Fallback polling just in case of weird race conditions with script execution
    return new Promise((resolve, reject) => {
      let retries = 0;
      const check = () => {
        const Email = (window as any).Email;
        if (Email && typeof Email.send === 'function') {
          resolve(Email);
        } else if (retries < maxRetries) {
          retries++;
          setTimeout(check, interval);
        } else {
          reject(new Error("SmtpJS Email library failed to initialize after loading."));
        }
      };
      check();
    });
  } catch (error) {
    throw error;
  }
};

