    return null;
  }

  return {
    Host: "smtp.gmail.com",
    Port: 587,
    Username: user,
    Password: pass,
  };
};

/**
 * Robustly loads the SmtpJS script with retries.
 */
const ensureSmtpLoaded = async (retries = 3): Promise<any> => {
  const scriptUrl = "https://smtpjs.com/v3/smtp.js";

  const attemptLoad = (): Promise<any> => {
    return new Promise((resolve, reject) => {
      // Check if already loaded
      if ((window as any).Email && typeof (window as any).Email.send === 'function') {
        return resolve((window as any).Email);
      }

      // Check for existing script tags to avoid duplicates
      const existing = document.querySelector(`script[src="${scriptUrl}"]`);
      if (existing) {
        existing.remove(); // Remove failed/stale attempts to try fresh
      }

      const script = document.createElement('script');
      script.src = `${scriptUrl}?v=${Date.now()}`; // Cache busting
      script.async = true;
      script.timeout = 5000; // 5 second timeout

      const onDone = () => {
        const Email = (window as any).Email;
        if (Email && typeof Email.send === 'function') {
          resolve(Email);
        } else {
          reject(new Error("SmtpJS loaded but Email object not found."));
        }
      };

      script.onload = onDone;
      script.onerror = () => reject(new Error("Network error loading SmtpJS."));

      document.head.appendChild(script);
    });
  };

  for (let i = 0; i < retries; i++) {
    try {
      return await attemptLoad();
    } catch (err) {
      console.warn(`[Email Service] Load attempt ${i + 1} failed. Retrying...`);
      if (i === retries - 1) throw err;
      await new Promise(r => setTimeout(r, 1000 * (i + 1))); // Exponential-ish backoff
    }
  }
};

