import { fetchAppConfig } from './supabase';

/**
 * ATON TECH Email Service Configuration
 */
const SMTP_JS_URL = "https://smtpjs.com/v3/smtp.js";
const GMAIL_HOST = "smtp.gmail.com";
const SMTP_PORT = 587;

/**
 * Internal state to track script loading
 */
let isScriptLoading = false;
let scriptLoadedPromise: Promise<any> | null = null;

/**
 * Fetches SMTP credentials from the Supabase config table.
 */
const getSmtpCredentials = async () => {
  const [user, pass] = await Promise.all([
    fetchAppConfig('smtp_user'),
    fetchAppConfig('smtp_pass')
  ]);

  if (!user || !pass) {
    throw new Error("SMTP credentials missing in database. Please configure 'smtp_user' and 'smtp_pass' in app_config.");
  }

  return {
    Host: GMAIL_HOST,
    Port: SMTP_PORT,
    Username: user,
    Password: pass,
  };
};

/**
 * Ensures the SmtpJS script is loaded into the document exactly once.
 */
const loadSmtpScript = (): Promise<any> => {
  if (scriptLoadedPromise) return scriptLoadedPromise;

  scriptLoadedPromise = new Promise((resolve, reject) => {
    // Check if window.Email already exists
    if ((window as any).Email?.send) {
      return resolve((window as any).Email);
    }

    const script = document.createElement('script');
    script.src = `${SMTP_JS_URL}?t=${Date.now()}`; // Cache busting
    script.async = true;

    const timeout = setTimeout(() => {
      reject(new Error("SmtpJS loading timed out (5s)"));
    }, 5000);

    script.onload = () => {
      clearTimeout(timeout);
      if ((window as any).Email?.send) {
        console.log("[Email Service] SmtpJS loaded successfully.");
        resolve((window as any).Email);
      } else {
        reject(new Error("SmtpJS script loaded but 'Email' object is unavailable."));
      }
    };

    script.onerror = () => {
      clearTimeout(timeout);
      scriptLoadedPromise = null; // Allow retry on next call
      reject(new Error("Failed to reach SmtpJS CDN. Please check internet connection."));
    };

    document.head.appendChild(script);
  });

  return scriptLoadedPromise;
};

/**
 * Core function to send an email using SmtpJS
 */
const sendMail = async (to: string, subject: string, body: string): Promise<boolean> => {
  try {
    const [config, Email] = await Promise.all([
      getSmtpCredentials(),
      loadSmtpScript()
    ]);

    const result = await Email.send({
      ...config,
      To: to,
      From: config.Username,
      Subject: subject,
      Body: body,
    });

    if (result === "OK") {
      return true;
    } else {
      console.error("[Email Service] SmtpJS Error:", result);
      return false;
    }
  } catch (error: any) {
    console.error("[Email Service] Operation Failed:", error.message || error);
    return false;
  }
};

