/**
 * ATON TECH Email Service Configuration
 */
const SMTP_JS_URL = "https://smtpjs.com/v3/smtp.js";
const GMAIL_HOST = "smtp.gmail.com";
const SMTP_PORT = 587;

/**
 * Internal state to track script loading to avoid redundant network calls.
 */
let scriptLoadedPromise: Promise<any> | null = null;

/**
 * Fetches SMTP credentials from the Supabase config table.
 */
const getSmtpCredentials = async () => {
  try {
    const [user, pass] = await Promise.all([
      fetchAppConfig('smtp_user'),
      fetchAppConfig('smtp_pass')
    ]);

    if (!user || !pass) {
      throw new Error("SMTP credentials missing in database. Please configure 'smtp_user' and 'smtp_pass' in app_config.");
    }

    return {
      Host: GMAIL_HOST,
      Port: SMTP_PORT,
      Username: user,
      Password: pass,
    };
  } catch (error) {
    console.error("[Email Service] Credential Fetch Failed:", error);
    throw error;
  }
};

/**
 * Ensures the SmtpJS script is loaded into the document.
 * Includes a retry loop and exponential backoff for resilience against transient network failures.
 */
const loadSmtpScript = (maxRetries = 3): Promise<any> => {
  if (scriptLoadedPromise) return scriptLoadedPromise;

  const attemptLoad = (currentRetry: number): Promise<any> => {
    return new Promise((resolve, reject) => {
      // Check if window.Email already exists globally
      if ((window as any).Email?.send) {
        return resolve((window as any).Email);
      }

      // Cleanup any previous failed script tags to avoid DOM pollution
      const existingScripts = document.querySelectorAll(`script[src^="${SMTP_JS_URL}"]`);
      existingScripts.forEach(s => s.remove());

      const script = document.createElement('script');
      // Apply cache busting on retries to bypass potential ISP/Local caching issues
      const cacheBust = currentRetry > 0 ? `?retry=${currentRetry}&t=${Date.now()}` : '';
      script.src = `${SMTP_JS_URL}${cacheBust}`;
      script.async = true;

      const timeoutDuration = 10000; // 10 second timeout for script loading
      const timeout = setTimeout(() => {
        script.onload = null;
        script.onerror = null;
        reject(new Error(`SmtpJS loading timed out after ${timeoutDuration / 1000}s`));
      }, timeoutDuration);

      script.onload = () => {
        clearTimeout(timeout);
        if ((window as any).Email?.send) {
          console.log(`[Email Service] SmtpJS initialized successfully (Attempt ${currentRetry + 1}).`);
          resolve((window as any).Email);
        } else {
          reject(new Error("SmtpJS script loaded but the 'Email' object was not initialized."));
        }
      };

      script.onerror = () => {
        clearTimeout(timeout);
        reject(new Error("Network failure reaching SmtpJS CDN. This may be caused by an ad-blocker or firewall."));
      };

      document.head.appendChild(script);
    });
  };

  // Wrap the retry logic in the cached promise
  scriptLoadedPromise = (async () => {
    let lastError: any;
    for (let i = 0; i < maxRetries; i++) {
      try {
        return await attemptLoad(i);
      } catch (err) {
        lastError = err;
        console.warn(`[Email Service] Load attempt ${i + 1} failed. Retrying in ${(i + 1)}s...`);
        if (i < maxRetries - 1) {
          // Exponential-like backoff
          await new Promise(r => setTimeout(r, 1000 * (i + 1)));
        }
      }
    }
    // Final failure: clear the cache so the next user action can trigger a fresh attempt
    scriptLoadedPromise = null;
    throw lastError;
  })();

  return scriptLoadedPromise;
};

/**
 * Core function to send an email using SmtpJS
 */
const sendMail = async (to: string, subject: string, body: string): Promise<boolean> => {
  try {
    // Parallelize loading the library and fetching credentials
    const [config, Email] = await Promise.all([
      getSmtpCredentials(),
      loadSmtpScript()
    ]);

    const result = await Email.send({
      ...config,
      To: to,
      From: config.Username,
      Subject: subject,
      Body: body,
    });

    if (result === "OK") {
      return true;
    } else {
      console.error("[Email Service] SmtpJS Provider Error:", result);
      return false;
    }
  } catch (error: any) {
    console.error("[Email Service] Operation Failed:", error.message || error);
    return false;
  }
};

