 * We implement the SmtpJS protocol directly to avoid loading external scripts
 * that often get blocked by CDNs, Firewalls, or Ad-blockers.
 */

const SMTP_ENDPOINT = "https://smtpjs.com/v1/send.aspx";

/**
 * Fetches SMTP credentials from the Supabase config table.
 */
const getSmtpCredentials = async () => {
  try {
    const [user, pass] = await Promise.all([
      fetchAppConfig('smtp_user'),
      fetchAppConfig('smtp_pass')
    ]);

    if (!user || !pass) {
      throw new Error("SMTP credentials missing in database. Please configure 'smtp_user' and 'smtp_pass' in app_config.");
    }

    return {
      Host: "smtp.gmail.com",
      Port: 587,
      Username: user,
      Password: pass,
    };
  } catch (error) {
    console.error("[Email Service] Credential Fetch Failed:", error);
    throw error;
  }
};

/**
 * Internal function that mimics SmtpJS logic using native fetch.
 * This replaces the need for <script src="https://smtpjs.com/v3/smtp.js">
 */
const internalSmtpSend = async (params: any): Promise<string> => {
  try {
    params.nocache = Math.floor(1e6 * Math.random() + 1);
    params.Action = "Send";

    // SmtpJS expects a stringified JSON object as the body
    const response = await fetch(SMTP_ENDPOINT, {
      method: "POST",
      headers: {
        "Content-Type": "application/x-www-form-urlencoded"
      },
      body: JSON.stringify(params)
    });

    if (!response.ok) {
      throw new Error(`HTTP Error: ${response.status}`);
    }

    return await response.text();
  } catch (error: any) {
    console.error("[Email Service] Network/API Error:", error);
    throw new Error("Failed to communicate with the email provider.");
  }
};

/**
 * Core function to send an email
 */
const sendMail = async (to: string, subject: string, body: string): Promise<boolean> => {
  try {
    const config = await getSmtpCredentials();

    const result = await internalSmtpSend({
      ...config,
      To: to,
      From: config.Username,
      Subject: subject,
      Body: body,
    });

    if (result === "OK") {
      console.log(`[Email Service] Success: Email sent to ${to}`);
      return true;
    } else {
      console.error("[Email Service] SmtpJS Provider Error:", result);
      return false;
    }
  } catch (error: any) {
    console.error("[Email Service] Operation Failed:", error.message || error);
    return false;
  }
};

