/**
 * Fetches EmailJS configuration from Supabase.
 * Expects keys: 'emailjs_service_id', 'emailjs_template_id', 'emailjs_public_key'
 */
const getEmailJSConfig = async (): Promise<EmailJSConfig> => {
  const [serviceId, templateId, publicKey] = await Promise.all([
    fetchAppConfig('emailjs_service_id'),
    fetchAppConfig('emailjs_template_id'),
    fetchAppConfig('emailjs_public_key')
  ]);

  if (!serviceId || !templateId || !publicKey) {
    throw new Error("EmailJS configuration missing in database. Check 'emailjs_service_id', 'emailjs_template_id', and 'emailjs_public_key' in app_config.");
  }

  return { serviceId, templateId, publicKey };
};

/**
 * Sends a lead notification to the business owner and an optional auto-reply to the user.
 * In EmailJS, you typically have one template for notifications. 
 * If you have a separate auto-reply template, you would call this again with a different template ID.
 */
export const sendLeadNotification = async (data: any): Promise<boolean> => {
  try {
    const config = await getEmailJSConfig();

    // Mapping form data to EmailJS template variables
    // Ensure your EmailJS template uses these exact names: {{from_name}}, {{user_email}}, {{user_phone}}, {{company_name}}, {{message}}
    const templateParams = {
      from_name: data.fullName,
      user_email: data.email,
      user_phone: data.phone,
      company_name: data.companyName || 'N/A',
      message: data.message,
      reply_to: data.email,
    };

    const response = await emailjs.send(
      config.serviceId,
      config.templateId,
      templateParams,
      config.publicKey
    );

    if (response.status === 200) {
      console.log("[Email Service] Lead notification sent successfully via EmailJS.");
      return true;
    } else {
      console.error("[Email Service] EmailJS Response Error:", response.text);
      return false;
    }
  } catch (error: any) {
    console.error("[Email Service] Failed to send email:", error.message || error);
    return false;
  }
};

/**
 * Sends an automated 'Thank You' reply to the customer.
 * Note: For EmailJS, it's often better to create a separate template for this.
 * We fetch a specific template ID for the auto-reply if it exists, otherwise we skip.
 */
export const sendAutoReply = async (userEmail: string, userName: string): Promise<boolean> => {
  try {
    const serviceId = await fetchAppConfig('emailjs_service_id');
    const templateId = await fetchAppConfig('emailjs_template_id_autoreply'); // Specific template for customers
    const publicKey = await fetchAppConfig('emailjs_public_key');

    if (!templateId || !serviceId || !publicKey) {
      console.warn("[Email Service] Auto-reply skipped: 'emailjs_template_id_autoreply' not configured.");
      return true; // We don't want to break the main flow if only the auto-reply is missing
    }

    const templateParams = {
      to_name: userName,
      user_email: userEmail,
    };

    const response = await emailjs.send(
      serviceId,
      templateId,
      templateParams,
      publicKey
    );

    return response.status === 200;
  } catch (error) {
    console.error("[Email Service] Auto-reply failed:", error);
    return false;
  }
};

