import emailjs from '@emailjs/browser';
import { fetchAppConfig } from './supabase';

/**
 * ATON TECH Email Service - Robust EmailJS Implementation
 * 
 * SETUP INSTRUCTIONS:
 * 1. Create an account at https://www.emailjs.com/
 * 2. Add these keys to your Supabase 'app_config' table:
 *    - emailjs_service_id
 *    - emailjs_template_id
 *    - emailjs_public_key
 *    - emailjs_template_id_autoreply (optional)
 */

interface EmailJSConfig {
  serviceId: string;
  templateId: string;
  publicKey: string;
  autoReplyTemplateId: string | null;
  isMock: boolean;
}

let cachedConfig: EmailJSConfig | null = null;

/**
 * Hardcoded fallbacks for local development or if Supabase keys are missing.
 * Replace these strings with your real keys if you don't want to use the database.
 */
const LOCAL_FALLBACK = {
  serviceId: '', // e.g., 'service_abcdef'
  templateId: '', // e.g., 'template_xyz123'
  publicKey: '',  // e.g., 'user_987654321'
  autoReplyTemplateId: null
};

/**
 * Fetches and caches EmailJS configuration.
 */
const getEmailJSConfig = async (): Promise<EmailJSConfig> => {
  if (cachedConfig) return cachedConfig;

  try {
    console.debug("[Email Service] Fetching configuration...");
    const [serviceId, templateId, publicKey, autoReplyTemplateId] = await Promise.all([
      fetchAppConfig('emailjs_service_id'),
      fetchAppConfig('emailjs_template_id'),
      fetchAppConfig('emailjs_public_key'),
      fetchAppConfig('emailjs_template_id_autoreply')
    ]);

    // Use DB values or local fallbacks
    const finalServiceId = serviceId || LOCAL_FALLBACK.serviceId;
    const finalTemplateId = templateId || LOCAL_FALLBACK.templateId;
    const finalPublicKey = publicKey || LOCAL_FALLBACK.publicKey;

    if (!finalServiceId || !finalTemplateId || !finalPublicKey) {
      console.warn(
        "[Email Service] Missing configuration. Entering 'Mock Mode' for UI functionality.\n" +
        "To enable real emails, add 'emailjs_service_id', 'emailjs_template_id', and 'emailjs_public_key' to your Supabase 'app_config' table."
      );
      cachedConfig = { 
        serviceId: 'mock_service', 
        templateId: 'mock_template', 
        publicKey: 'mock_key', 
        autoReplyTemplateId: null,
        isMock: true 
      };
      return cachedConfig;
    }

    cachedConfig = { 
      serviceId: finalServiceId, 
      templateId: finalTemplateId, 
      publicKey: finalPublicKey, 
      autoReplyTemplateId: autoReplyTemplateId || LOCAL_FALLBACK.autoReplyTemplateId,
      isMock: false
    };

    emailjs.init(cachedConfig.publicKey);
    return cachedConfig;
  } catch (error) {
    console.error("[Email Service] Config fetch failed, using mock mode:", error);
    return { 
      serviceId: 'error_mock', 
      templateId: 'error_mock', 
      publicKey: 'error_mock', 
      autoReplyTemplateId: null, 
      isMock: true 
    };
  }
};

/**
 * Sends a lead notification to the business owner.
 */
export const sendLeadNotification = async (data: any): Promise<boolean> => {
  try {
    const config = await getEmailJSConfig();

    if (config.isMock) {
      console.info("[Email Service][Mock Mode] Simulation lead notification for:", data.fullName);
      await new Promise(resolve => setTimeout(resolve, 800)); // Simulate network lag
      return true;
    }

    const templateParams = {
      from_name: data.fullName,
      user_email: data.email,
      user_phone: data.phone,
      company_name: data.companyName || 'N/A',
      message: data.message,
      reply_to: data.email,
    };

    const response = await emailjs.send(
      config.serviceId,
      config.templateId,
      templateParams
    );

    return response.status === 200;
  } catch (error: any) {
    console.error("[Email Service] Lead notification failed:", error.message || error);
    return false;
  }
};

/**
 * Sends an automated 'Thank You' reply to the customer.
 */
export const sendAutoReply = async (userEmail: string, userName: string): Promise<boolean> => {
  try {
    const config = await getEmailJSConfig();

    if (config.isMock) {
      console.info("[Email Service][Mock Mode] Simulating auto-reply to:", userEmail);
      return true;
    }

